package com.ruoyi.boost;

import java.security.SecureRandom;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import static com.ruoyi.boost.BoostDb.*;
import static com.ruoyi.boost.BoostInput.*;

/** Free, non-purchasable points only. No money, membership or growth conversion. */
@Service
public class BoostRewards {
    private final BoostDb db; private final BoostRewardsMedia media;
    private final SecureRandom random=new SecureRandom(); private final ObjectMapper json=new ObjectMapper();
    @Value("${boost.free-points-draw-enabled:false}") private boolean drawEnabled;
    public BoostRewards(BoostDb db,BoostRewardsMedia media){this.db=db;this.media=media;}
    public boolean drawEnabled(){return drawEnabled;}
    private String key(Map<String,Object>b){return text(b,"requestKey",8,64);}
    private void account(long member){db.activeMember(member);if(db.list("SELECT member_id FROM boost_points_account WHERE member_id=?",member).isEmpty())db.run("INSERT INTO boost_points_account(member_id) VALUES (?)",member);db.one("SELECT balance FROM boost_points_account WHERE member_id=? FOR UPDATE",member);}
    private long balance(long member){return db.count("SELECT COALESCE(MAX(balance),0) FROM boost_points_account WHERE member_id=?",member);}
    private void entry(long member,long delta,String kind,String event,String hash,String note,Long admin){long next=Math.addExact(balance(member),delta);BoostException.require(next>=0&&next<=1000000000L,"积分不足或已达余额上限");db.run("UPDATE boost_points_account SET balance=? WHERE member_id=?",next,member);db.run("INSERT INTO boost_points_entry(member_id,event_key,request_hash,delta,balance,kind,note,admin_id) VALUES (?,?,?,?,?,?,?,?)",member,event,hash,delta,next,kind,note,admin);}
    private void audit(long admin,String action,long id,String note){db.run("INSERT INTO boost_audit(admin_id,action,target_id,note) VALUES (?,?,?,?)",admin,action,id,note);}
    public Object points(long member,Map<String,String>q){db.activeMember(member);int p=page(q);return map("balance",balance(member),"items",db.list("SELECT id,delta,balance,kind,note,created_at FROM boost_points_entry WHERE member_id=? ORDER BY id DESC LIMIT 20 OFFSET ?",member,(p-1)*20),"total",db.count("SELECT COUNT(*) FROM boost_points_entry WHERE member_id=?",member),"sourceRule","仅免费发放，不可购买、转让、提现；与成长值分开");}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Object grant(long admin,long member,Map<String,Object>b){String k=key(b),note=text(b,"note",2,200),hash=BoostIdempotency.digest(b);long amount=number(b,"amount",1,1000000);BoostException.require("ACTIVE".equals(str(db.one("SELECT status FROM boost_member WHERE id=? FOR UPDATE",member),"status")),"目标玩家已停用，不能发放积分");account(member);List<Map<String,Object>>old=db.list("SELECT * FROM boost_points_entry WHERE member_id=? AND event_key=?",member,"grant:"+k);if(!old.isEmpty()){BoostIdempotency.same(old.get(0),hash);return map("id",old.get(0).get("id"),"balance",balance(member));}entry(member,amount,"FREE_GRANT","grant:"+k,hash,note,admin);audit(admin,"rewards:free-grant",member,note);return map("balance",balance(member));}
    public Object goods(Map<String,String>q,boolean admin){String filter=admin?"1=1":"status='ACTIVE'";return map("items",db.list("SELECT * FROM boost_reward_goods WHERE "+filter+" ORDER BY id DESC LIMIT 20 OFFSET ?",(page(q)-1)*20),"total",db.count("SELECT COUNT(*) FROM boost_reward_goods WHERE "+filter));}
    public Map<String,Object> good(long id,boolean admin){Map<String,Object>g=db.one("SELECT * FROM boost_reward_goods WHERE id=?",id);if(!admin&&!"ACTIVE".equals(str(g,"status")))throw new BoostException(404,"商品已下架");return g;}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Object saveGoods(long admin,Long id,Map<String,Object>b){String title=text(b,"title",1,60),kind=choice(b,"kind","BADGE","PHYSICAL"),status=choice(b,"status","DRAFT","ACTIVE"),image=media.validate(str(b,"image")),description=text(b,"description",1,1000);long cost=number(b,"pointsCost",1,1000000),stock=number(b,"stock",0,1000000);String code=null;
        if("BADGE".equals(kind)){code=text(b,"badgeCode",1,32);BoostException.require(code.matches("[A-Z0-9_]+"),"勋章代码只能使用大写字母、数字和下划线");}
        if(id==null){BoostException.require(code==null||db.count("SELECT COUNT(*) FROM boost_reward_goods WHERE badge_code=?",code)==0,"勋章代码已存在");id=db.insert("INSERT INTO boost_reward_goods(title,kind,badge_code,image,description,points_cost,stock,status) VALUES (?,?,?,?,?,?,?,?)",title,kind,code,image,description,cost,stock,status);}
        else{Map<String,Object>old=db.one("SELECT * FROM boost_reward_goods WHERE id=? FOR UPDATE",id);if(number(b,"expectedStock",0,1000000)!=num(old,"stock"))throw new BoostException(409,"库存已发生变化，请刷新商品后重新编辑");BoostException.require(kind.equals(str(old,"kind"))&&Objects.equals(code,old.get("badgeCode")),"商品类型与勋章代码创建后不可更改");db.run("UPDATE boost_reward_goods SET title=?,image=?,description=?,points_cost=?,stock=?,status=?,revision=revision+1 WHERE id=?",title,image,description,cost,stock,status,id);}
        audit(admin,"rewards:goods-save",id,title);return good(id,true);
    }
    private boolean held(long member,Map<String,Object>g){return "BADGE".equals(str(g,"kind"))&&db.count("SELECT COUNT(*) FROM boost_member_badge WHERE member_id=? AND badge_code=?",member,str(g,"badgeCode"))>0;}
    private long award(long member,Map<String,Object>g,String source,long spent,String k,String hash){long id=num(g,"id");BoostException.require("ACTIVE".equals(str(g,"status"))&&num(g,"stock")>0,"奖品已下架或库存不足");BoostException.require(!held(member,g),"你已拥有这枚勋章，无需重复领取");db.run("UPDATE boost_reward_goods SET stock=stock-1 WHERE id=?",id);String state="BADGE".equals(str(g,"kind"))?"COMPLETED":"WAIT_ADDRESS";
        long order=db.insert("INSERT INTO boost_reward_order(member_id,goods_id,title,kind,image,badge_code,source,points_spent,request_key,request_hash,status) VALUES (?,?,?,?,?,?,?,?,?,?,?)",member,id,g.get("title"),g.get("kind"),g.get("image"),g.get("badgeCode"),source,spent,k,hash,state);
        if("BADGE".equals(str(g,"kind")))db.run("INSERT INTO boost_member_badge(member_id,badge_code,title,image) VALUES (?,?,?,?)",member,g.get("badgeCode"),g.get("title"),g.get("image"));return order;
    }
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Object redeem(long member,long goods,Map<String,Object>b){String k=key(b),hash=BoostIdempotency.digest(map("goodsId",goods,"body",b));account(member);List<Map<String,Object>>old=db.list("SELECT * FROM boost_reward_order WHERE member_id=? AND request_key=?",member,"redeem:"+k);if(!old.isEmpty()){BoostIdempotency.same(old.get(0),hash);return detail(member,num(old.get(0),"id"));}Map<String,Object>g=db.one("SELECT * FROM boost_reward_goods WHERE id=? FOR UPDATE",goods);long cost=num(g,"pointsCost");quote(b,g);entry(member,-cost,"REDEEM","redeem:"+k,hash,"兑换："+str(g,"title"),null);long id=award(member,g,"REDEEM",cost,"redeem:"+k,hash);db.notify(member,"积分兑换完成",str(g,"title")+"已领取，请查看兑换记录。",null);return detail(member,id);}
    public Object badges(long member){return db.list("SELECT b.badge_code,b.title,b.image,b.earned_at FROM boost_member_badge b JOIN boost_member m ON m.id=b.member_id WHERE b.member_id=? AND m.status='ACTIVE' ORDER BY b.earned_at DESC",member);}
    public Object orders(long member,Map<String,String>q){db.activeMember(member);return map("items",db.list("SELECT id,title,kind,image,source,points_spent,status,created_at FROM boost_reward_order WHERE member_id=? ORDER BY id DESC LIMIT 20 OFFSET ?",member,(page(q)-1)*20),"total",db.count("SELECT COUNT(*) FROM boost_reward_order WHERE member_id=?",member));}
    public Map<String,Object> detail(long member,long id){Map<String,Object>o=db.one("SELECT * FROM boost_reward_order WHERE id=? AND member_id=?",id,member);o.remove("requestKey");o.remove("requestHash");return o;}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Object address(long member,long id,Map<String,Object>b){db.activeMember(member);Map<String,Object>o=db.one("SELECT * FROM boost_reward_order WHERE id=? AND member_id=? FOR UPDATE",id,member);BoostException.require(List.of("WAIT_ADDRESS","WAIT_SHIP").contains(str(o,"status")),"已发货后不能修改地址");String recipient=text(b,"recipient",1,50),phone=text(b,"phone",11,11),address=text(b,"address",5,300);BoostException.require(phone.matches("1[3-9][0-9]{9}"),"请填写正确的大陆手机号");db.run("UPDATE boost_reward_order SET recipient=?,phone=?,address=?,status='WAIT_SHIP' WHERE id=?",recipient,phone,address,id);return detail(member,id);}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Object receive(long member,long id){db.activeMember(member);Map<String,Object>o=db.one("SELECT * FROM boost_reward_order WHERE id=? AND member_id=? FOR UPDATE",id,member);if("COMPLETED".equals(str(o,"status")))return detail(member,id);BoostException.require("SHIPPED".equals(str(o,"status")),"订单尚未发货");db.run("UPDATE boost_reward_order SET status='COMPLETED',received_at=CURRENT_TIMESTAMP WHERE id=?",id);return detail(member,id);}
    public Object adminOrders(Map<String,String>q){String state=q.getOrDefault("status","");BoostException.require(state.isEmpty()||List.of("WAIT_ADDRESS","WAIT_SHIP","SHIPPED","COMPLETED").contains(state),"状态无效");String where=state.isEmpty()?"1=1":"status=?";List<Object>args=new ArrayList<>();if(!state.isEmpty())args.add(state);long total=db.count("SELECT COUNT(*) FROM boost_reward_order WHERE "+where,args.toArray());args.add((page(q)-1)*20);List<Map<String,Object>>rows=db.list("SELECT * FROM boost_reward_order WHERE "+where+" ORDER BY id DESC LIMIT 20 OFFSET ?",args.toArray());rows.forEach(r->{r.remove("requestKey");r.remove("requestHash");});return map("items",rows,"total",total);}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Object ship(long admin,long id,Map<String,Object>b){long member=num(db.one("SELECT member_id FROM boost_reward_order WHERE id=?",id),"memberId");db.one("SELECT id FROM boost_member WHERE id=? FOR UPDATE",member);Map<String,Object>o=db.one("SELECT * FROM boost_reward_order WHERE id=? FOR UPDATE",id);String carrier=text(b,"carrier",1,60),tracking=text(b,"trackingNo",4,60);BoostException.require(tracking.matches("[A-Za-z0-9-]+"),"物流单号格式无效");if(List.of("SHIPPED","COMPLETED").contains(str(o,"status"))){BoostException.require(carrier.equals(str(o,"carrier"))&&tracking.equals(str(o,"trackingNo")),"此订单已使用其他物流信息发货");return true;}BoostException.require("WAIT_SHIP".equals(str(o,"status")),"请等待用户填写收货信息");db.run("UPDATE boost_reward_order SET carrier=?,tracking_no=?,status='SHIPPED',shipped_at=CURRENT_TIMESTAMP WHERE id=?",carrier,tracking,id);audit(admin,"rewards:ship",id,carrier);db.notify(num(o,"memberId"),"兑换实物已发货","请在兑换记录查看物流并确认收货。",null);return true;}
    public Object activities(boolean admin){return map("drawEnabled",drawEnabled,"items",db.list("SELECT * FROM boost_reward_activity "+(admin?"":"WHERE status='ACTIVE'")+" ORDER BY id DESC LIMIT 100"));}
    private List<Map<String,Object>> prizes(long id){return db.list("SELECT p.id,p.goods_id,p.weight,p.position,g.title,g.kind,g.badge_code,g.image,g.stock,g.status FROM boost_reward_prize p LEFT JOIN boost_reward_goods g ON g.id=p.goods_id WHERE p.activity_id=? ORDER BY p.position",id);}
    public Map<String,Object> activity(long id,Long member,boolean admin){Map<String,Object>a=db.one("SELECT * FROM boost_reward_activity WHERE id=?",id);if(!admin&&!"ACTIVE".equals(str(a,"status")))throw new BoostException(404,"活动尚未开放");List<Map<String,Object>>pool=prizes(id);long sum=0;for(Map<String,Object>p:pool){boolean available=p.get("goodsId")==null||("ACTIVE".equals(str(p,"status"))&&num(p,"stock")>0&&(member==null||!held(member,p)));p.put("available",available);p.put("title",p.get("goodsId")==null?"下次好运":p.get("title"));if(available)sum+=num(p,"weight");}for(Map<String,Object>p:pool)p.put("probability",Boolean.TRUE.equals(p.get("available"))&&sum>0?(double)num(p,"weight")/sum:0);a.put("prizes",pool);a.put("drawEnabled",drawEnabled);a.put("rule","免费积分活动；每次按当时可领取奖品的权重抽取，售罄、下架及已持有勋章退出奖池；五连逐次更新奖池。积分不能购买、转让或提现。");return a;}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Object saveActivity(long admin,Long id,Map<String,Object>b){String title=text(b,"title",1,60),cover=media.validate(str(b,"cover")),description=text(b,"description",1,1000),status=choice(b,"status","DRAFT","ACTIVE");long cost=number(b,"pointsCost",1,1000000);Timestamp start=time(b,"startsAt"),end=time(b,"endsAt");BoostException.require(end.after(start),"结束时间必须晚于开始时间");BoostException.require(b.get("prizes") instanceof List,"请配置奖池");List<?>pool=(List<?>)b.get("prizes");BoostException.require(pool.size()>=2&&pool.size()<=8,"奖池需配置 2 至 8 个格子");Set<Long>seen=new HashSet<>();List<Map<String,Object>>validated=new ArrayList<>();for(Object item:pool){BoostException.require(item instanceof Map,"奖池格式无效");Map<String,Object>p=(Map<String,Object>)item;Long gid=p.get("goodsId")==null?null:number(p,"goodsId",1,Long.MAX_VALUE);long weight=number(p,"weight",1,1000000);BoostException.require(seen.add(gid),"奖品不能重复配置");if(gid!=null)good(gid,true);validated.add(map("goodsId",gid,"weight",weight));}BoostException.require(!"ACTIVE".equals(status)||!cover.isEmpty(),"上架活动请上传封面图");
        if(id==null)id=db.insert("INSERT INTO boost_reward_activity(title,cover,description,points_cost,starts_at,ends_at,status) VALUES (?,?,?,?,?,?,?)",title,cover,description,cost,start,end,status);else{db.one("SELECT id FROM boost_reward_activity WHERE id=? FOR UPDATE",id);db.run("UPDATE boost_reward_activity SET title=?,cover=?,description=?,points_cost=?,starts_at=?,ends_at=?,status=?,revision=revision+1 WHERE id=?",title,cover,description,cost,start,end,status,id);db.run("DELETE FROM boost_reward_prize WHERE activity_id=?",id);}for(Long gid:new TreeSet<Long>(seen.stream().filter(Objects::nonNull).toList()))db.one("SELECT id FROM boost_reward_goods WHERE id=? FOR UPDATE",gid);int position=0;for(Map<String,Object>p:validated)db.run("INSERT INTO boost_reward_prize(activity_id,goods_id,weight,position) VALUES (?,?,?,?)",id,p.get("goodsId"),p.get("weight"),position++);audit(admin,"rewards:activity-save",id,title);return activity(id,null,true);}
    private void quote(Map<String,Object>b,Map<String,Object>item){if(number(b,"expectedPointsCost",1,1000000)!=num(item,"pointsCost")||number(b,"expectedRevision",1,Integer.MAX_VALUE)!=num(item,"revision"))throw new BoostException(409,"积分价格或活动内容已更新，请刷新并重新确认");}
    private Timestamp time(Map<String,Object>b,String field){try{return Timestamp.valueOf(LocalDateTime.parse(text(b,field,16,30)));}catch(Exception e){throw new BoostException(400,"活动时间格式应为 YYYY-MM-DDTHH:mm:ss");}}
    @Transactional(isolation=Isolation.READ_COMMITTED)
    public Object draw(long member,long id,Map<String,Object>b){String k=key(b),hash=BoostIdempotency.digest(map("activityId",id,"body",b));long count=number(b,"count",1,5);BoostException.require(count==1||count==5,"只支持单抽或五连抽");account(member);List<Map<String,Object>>old=db.list("SELECT * FROM boost_reward_draw WHERE member_id=? AND request_key=?",member,k);if(!old.isEmpty()){BoostIdempotency.same(old.get(0),hash);return drawResult(old.get(0),member);}BoostException.require(drawEnabled,"免费积分规则待确认，抽奖暂未开放");Map<String,Object>a=db.one("SELECT * FROM boost_reward_activity WHERE id=? FOR UPDATE",id);quote(b,a);Instant now=Instant.now();BoostException.require("ACTIVE".equals(str(a,"status"))&&now.isAfter(LocalDateTime.parse(str(a,"startsAt")).atZone(ZoneId.systemDefault()).toInstant())&&now.isBefore(LocalDateTime.parse(str(a,"endsAt")).atZone(ZoneId.systemDefault()).toInstant()),"活动未开始或已结束");
        List<Map<String,Object>>pool=prizes(id);Map<Long,Map<String,Object>>goods=new TreeMap<>();for(Map<String,Object>p:pool)if(p.get("goodsId")!=null)goods.put(num(p,"goodsId"),null);for(Long gid:goods.keySet())goods.put(gid,db.one("SELECT * FROM boost_reward_goods WHERE id=? FOR UPDATE",gid));long cost=Math.multiplyExact(num(a,"pointsCost"),count);entry(member,-cost,"DRAW","draw:"+k,hash,"活动："+str(a,"title")+" · "+count+" 次",null);List<Map<String,Object>>results=new ArrayList<>();
        for(int i=0;i<count;i++){List<Map<String,Object>>available=new ArrayList<>();long sum=0;for(Map<String,Object>p:pool){Map<String,Object>g=p.get("goodsId")==null?null:goods.get(num(p,"goodsId"));if(g==null||("ACTIVE".equals(str(g,"status"))&&num(g,"stock")>0&&!held(member,g))){available.add(p);sum+=num(p,"weight");}}BoostException.require(sum>0,"可领取奖品不足，整个请求已取消，不扣积分");long ticket=random.nextLong(sum),cursor=0;Map<String,Object>selected=null;for(Map<String,Object>p:available){cursor+=num(p,"weight");if(ticket<cursor){selected=p;break;}}List<Map<String,Object>>odds=new ArrayList<>();for(Map<String,Object>p:available)odds.add(map("prizeId",p.get("id"),"weight",p.get("weight"),"probability",(double)num(p,"weight")/sum,"position",p.get("position"),"goodsId",p.get("goodsId"),"title",p.get("goodsId")==null?"下次好运":goods.get(num(p,"goodsId")).get("title"),"kind",p.get("goodsId")==null?"NONE":goods.get(num(p,"goodsId")).get("kind")));Map<String,Object>g=selected.get("goodsId")==null?null:goods.get(num(selected,"goodsId"));Long order=null;if(g!=null){order=award(member,g,"DRAW",0,"draw:"+k+":"+i,hash);g.put("stock",num(g,"stock")-1);}results.add(map("position",selected.get("position"),"title",g==null?"下次好运":g.get("title"),"orderId",order,"kind",g==null?"NONE":g.get("kind"),"odds",odds));}
        try{long draw=db.insert("INSERT INTO boost_reward_draw(member_id,activity_id,request_key,request_hash,draw_count,points_spent,results) VALUES (?,?,?,?,?,?,?)",member,id,k,hash,count,cost,json.writeValueAsString(results));return drawResult(db.one("SELECT * FROM boost_reward_draw WHERE id=?",draw),member);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}
    }
    private Object drawResult(Map<String,Object>r,long member){try{return map("id",r.get("id"),"pointsSpent",r.get("pointsSpent"),"balance",balance(member),"results",json.readValue(str(r,"results"),List.class));}catch(Exception e){throw new IllegalStateException(e);}}
    public Object draws(long member,Map<String,String>q){db.activeMember(member);List<Map<String,Object>>rows=db.list("SELECT * FROM boost_reward_draw WHERE member_id=? ORDER BY id DESC LIMIT 20 OFFSET ?",member,(page(q)-1)*20);List<Object>items=new ArrayList<>();for(Map<String,Object>r:rows){Map<String,Object>item=(Map<String,Object>)drawResult(r,member);item.put("createdAt",r.get("createdAt"));items.add(item);}return map("items",items,"total",db.count("SELECT COUNT(*) FROM boost_reward_draw WHERE member_id=?",member));}
}
